/* Example: simple application-level sharding lookup in pseudocode */
function shardForUser(userId, shardCount) {
  // deterministic hash-to-shard mapping
  return (hash64(userId) % shardCount) + 1; // returns shard index 1..N
}

// usage
let shard = shardForUser(123456789, 16); // route queries for this user to Postgres shard `shard`

