/* Python example using a simple decorator-style circuit breaker */
import time
from functools import wraps

class SimpleCB:
    def __init__(self, fail_threshold=3, reset_timeout=10):
        self.fail_threshold = fail_threshold
        self.reset_timeout = reset_timeout
        self.failures = 0
        self.opened_at = None

    def __call__(self, fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            if self.opened_at:
                if time.time() - self.opened_at < self.reset_timeout:
                    raise Exception('CircuitOpen')
                else:
                    # move to half-open: allow one trial
                    pass
            try:
                result = fn(*args, **kwargs)
            except Exception:
                self.failures += 1
                if self.failures >= self.fail_threshold:
                    self.opened_at = time.time()
                raise
            else:
                self.failures = 0
                self.opened_at = None
                return result
        return wrapped

# Usage
# cb = SimpleCB()
# @cb
# def call_service():
#     ...
